CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid REFERENCES tenants(id), email text UNIQUE NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','tenant')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE activation_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE system_settings (setting_key text PRIMARY KEY, value_ciphertext bytea NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE knowledge_bases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), slug text NOT NULL, name text NOT NULL, database_config_ciphertext bytea NOT NULL, s3_config_ciphertext bytea NOT NULL, embedding_config_ciphertext bytea NOT NULL, enrichment_config_ciphertext bytea NOT NULL, chunk_config jsonb NOT NULL, webhook_url text, webhook_secret_ciphertext bytea, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,slug));
CREATE TABLE api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), kb_id uuid REFERENCES knowledge_bases(id), client_name text NOT NULL, key_prefix text NOT NULL, key_hash text NOT NULL UNIQUE, scopes text[] NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz);
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), kb_id uuid NOT NULL REFERENCES knowledge_bases(id), kind text NOT NULL CHECK(kind IN ('ingest','reindex','rejection')), status text NOT NULL CHECK(status IN ('queued','running','succeeded','failed','rejected')), payload jsonb NOT NULL DEFAULT '{}'::jsonb, error text, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE usage_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, occurred_at timestamptz NOT NULL DEFAULT now(), tenant_id uuid NOT NULL REFERENCES tenants(id), kb_id uuid REFERENCES knowledge_bases(id), api_key_id uuid REFERENCES api_keys(id), event_type text NOT NULL, units integer NOT NULL DEFAULT 1, latency_ms integer, metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE INDEX usage_events_tenant_time ON usage_events(tenant_id, occurred_at DESC);
